import datetime
import re

from ta_moler.events.unix_syslog.genericunix_syslog_lineevent import GenericUnixSyslogLineEvent


class ExecutingRecoveryActionSiteReset(GenericUnixSyslogLineEvent):
    """ExecutingRecoveryActionSiteReset event class."""

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for 'ExecutingRecoveryActionSiteReset'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        # 001146 21.08 08:20:45.337 [192.168.255.129] 28 FCT-2011-3-FRI <2020-08-21T06:20:44.190874Z> 56BE-FRI INF/FRI/FRI, [RecoveryActionController #0#] Executing recovery action SiteReset for {active 1806; /MRBTS-1/RAT-1/NRTS-4/NRBTS_L-15; #7}
        self._re_detect_pattern = re.compile(r"Executing recovery action SiteReset for")

        super(ExecutingRecoveryActionSiteReset, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self._re_detect_pattern], match="any"
        )


EVENT_OUTPUT = """
001146 21.08 08:20:45.337 [192.168.255.129] 28 FCT-2011-3-FRI <2020-08-21T06:20:44.190874Z> 56BE-FRI INF/FRI/FRI, [RecoveryActionController #0#] Executing recovery action SiteReset for {active 1806; /MRBTS-1/RAT-1/NRTS-4/NRBTS_L-15; #7}
"""

